// ---------------------------------------------------------------------------
// test_signature_matcher.cpp — CTest #77
// Validates scan/SignatureMatcher.h: the streaming Aho-Corasick multi-pattern
// matcher. The corpus is generated by testdata/tools/Gen-SignatureMatcherGolden.py
// (an INDEPENDENT oracle: expected matches are computed with a naive per-pattern
// byte scan, not by replicating the automaton). Agreement is a real cross-check.
// ---------------------------------------------------------------------------
#include "scan/SignatureMatcher.h"

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

namespace {

int g_fail = 0;
#define CHECK(cond, msg) do {                                            \
    if (!(cond)) { std::printf("  FAIL: %s\n", msg); ++g_fail; }        \
} while (0)

std::vector<uint8_t> ReadFile(const std::string& path)
{
    std::ifstream f(path, std::ios::binary);
    std::vector<uint8_t> out((std::istreambuf_iterator<char>(f)),
                             std::istreambuf_iterator<char>());
    return out;
}

std::string FindGoldenDir()
{
    const char* env = std::getenv("PHOENIX_GOLDEN_ROOT");
    std::vector<std::string> candidates;
    if (env && *env) candidates.emplace_back(std::string(env) + "/");
    candidates.emplace_back("testdata/signature-matcher-golden/");
    candidates.emplace_back("../testdata/signature-matcher-golden/");
    candidates.emplace_back("../../testdata/signature-matcher-golden/");
    candidates.emplace_back("../../../testdata/signature-matcher-golden/");
    candidates.emplace_back("../../../../testdata/signature-matcher-golden/");
    for (const std::string& d : candidates) {
        std::ifstream f(d + "manifest.json");
        if (f.good()) return d;
    }
    return "testdata/signature-matcher-golden/";
}

// Catalog mirrors Gen-SignatureMatcherGolden.py CATALOG (the independent oracle).
// (ext, header, headerOffset, secondary, secOffset, footer, maxSize, priority)
void BuildCatalog(std::vector<phoenix::MatchPattern>& pats)
{
    auto add = [&](const char* ext, const std::vector<uint8_t>& h, int off,
                   const std::vector<uint8_t>& sec, int soff,
                   const std::vector<uint8_t>& foot, uint64_t maxS, int pri) {
        phoenix::MatchPattern p;
        p.extension = std::wstring(ext, ext + std::strlen(ext));
        p.header = h; p.headerOffset = off;
        p.secondary = sec; p.secondaryOffset = soff;
        p.footer = foot; p.maxSize = maxS; p.priority = pri;
        pats.push_back(std::move(p));
    };
    add("jpg",  {0xFF,0xD8,0xFF,0xE0}, 0, {}, -1, {}, 50ull<<20, 0);
    add("png",  {0x89,0x50,0x4E,0x47}, 0, {}, -1, {}, 50ull<<20, 0);
    add("gif",  {'G','I','F','8'}, 0, {}, -1, {}, 50ull<<20, 0);
    add("zip",  {0x50,0x4B,0x03,0x04}, 0, {}, -1, {}, 50ull<<20, 0);
    add("pdf",  {'%','P','D','F'}, 0, {}, -1, {'E','O','F'}, 50ull<<20, 0);
    add("riff", {0x52,0x49,0x46,0x46}, 0, {'W','A','V','E'}, 8, {}, 50ull<<20, 1);
    add("mp4",  {0x00,0x00,0x00,0x18,0x66,0x74,0x79,0x70}, 4, {}, -1, {}, 50ull<<20, 0);
    add("cr2",  {'I','I',0x2A,0x00,0x10,0x00,0x00,0x00,'C','R',0x02,0x00}, 0, {}, -1, {}, 50ull<<20, 2);
}

struct ExpectedHit
{
    std::wstring ext;
    uint64_t fileStart;
    uint64_t magicOffset;
    int      headerOffset;
    bool     secondaryOk;
    bool     footerOk;
    int      priority;
    int      patternId;
};

std::vector<ExpectedHit> ParseCases(const std::string& path)
{
    std::vector<ExpectedHit> out;
    std::ifstream f(path);
    std::string line;
    while (std::getline(f, line)) {
        if (line.empty() || line[0] == '#') continue;
        std::istringstream ss(line);
        std::string ext, fs, mo, ho, so, fo, pr, pid;
        if (!(ss >> ext >> fs >> mo >> ho >> so >> fo >> pr >> pid)) continue;
        ExpectedHit e;
        e.ext = std::wstring(ext.begin(), ext.end());
        e.fileStart = std::stoull(fs); e.magicOffset = std::stoull(mo);
        e.headerOffset = std::stoi(ho);
        e.secondaryOk = (so == "1"); e.footerOk = (fo == "1");
        e.priority = std::stoi(pr); e.patternId = std::stoi(pid);
        out.push_back(e);
    }
    return out;
}

std::vector<std::pair<uint64_t,uint64_t>> ParseNegative(const std::string& path)
{
    std::vector<std::pair<uint64_t,uint64_t>> out;
    std::ifstream f(path);
    std::string line;
    while (std::getline(f, line)) {
        if (line.empty() || line[0] == '#') continue;
        std::istringstream ss(line);
        uint64_t a, b; std::string lab;
        if (!(ss >> a >> b >> lab)) continue;
        out.emplace_back(a, b);
    }
    return out;
}

bool operator==(const phoenix::SignatureHit& h, const ExpectedHit& e)
{
    return h.extension == e.ext && h.fileStart == e.fileStart &&
           h.magicOffset == e.magicOffset && h.secondaryOk == e.secondaryOk &&
           h.footerOk == e.footerOk && h.priority == e.priority;
}

struct Cmp
{
    bool operator()(const phoenix::SignatureHit& a, const phoenix::SignatureHit& b) const {
        if (a.fileStart != b.fileStart) return a.fileStart < b.fileStart;
        return a.patternId < b.patternId;
    }
    bool operator()(const ExpectedHit& a, const ExpectedHit& b) const {
        if (a.fileStart != b.fileStart) return a.fileStart < b.fileStart;
        return a.patternId < b.patternId;
    }
};

} // namespace

int main()
{
    const std::string dir = FindGoldenDir();
    std::printf("SignatureMatcher golden dir: %s\n", dir.c_str());

    std::vector<phoenix::MatchPattern> catalog;
    BuildCatalog(catalog);
    phoenix::SignatureMatcher matcher;
    CHECK(matcher.Build(std::move(catalog)), "build matcher from catalog");
    CHECK(matcher.PatternCount() == 8, "8 patterns built");

    // --- AC unit property: overlapping patterns {ab, bc} ----------------------
    {
        std::vector<phoenix::MatchPattern> ab;
        auto mk = [](const char* ext, std::vector<uint8_t> h){
            phoenix::MatchPattern p; p.extension = std::wstring(ext, ext+strlen(ext));
            p.header = h; return p;
        };
        ab.push_back(mk("ab", {'a','b'}));
        ab.push_back(mk("bc", {'b','c'}));
        phoenix::SignatureMatcher m;
        CHECK(m.Build(std::move(ab)), "build {ab,bc}");
        CHECK(m.StateCount() == 5, "overlapping AC has 5 states");
        std::vector<uint8_t> txt = {'a','b','c','a','b','c'};
        phoenix::MatchOptions o; o.alignment = 1;
        std::vector<phoenix::SignatureHit> hits;
        m.Scan(txt.data(), txt.size(), 0, o, hits);
        // "abcabc" -> ab@0, bc@1, ab@3, bc@4  (overlapping, output propagation)
        CHECK(hits.size() == 4, "abcabc yields 4 overlapping matches");
        std::sort(hits.begin(), hits.end(), Cmp());
        std::vector<uint64_t> starts;
        for (auto& h : hits) starts.push_back(h.fileStart);
        std::vector<uint64_t> want = {0,1,3,4};
        CHECK(starts == want, "overlapping match offsets {0,1,3,4}");
    }

    // --- golden corpus: single-buffer scan vs independent oracle ------------
    std::vector<uint8_t> image = ReadFile(dir + "disk_image.bin");
    CHECK(!image.empty(), "disk_image.bin loaded");
    auto expected = ParseCases(dir + "cases.tsv");
    auto negative = ParseNegative(dir + "negative.tsv");
    std::printf("  expected=%zu negative=%zu imageSize=%zu\n",
                expected.size(), negative.size(), image.size());

    phoenix::MatchOptions opt; opt.alignment = 1; opt.includeFooterSearch = true;
    std::vector<phoenix::SignatureHit> hits;
    matcher.Scan(image.data(), image.size(), 0, opt, hits);
    std::vector<phoenix::SignatureHit> sortedHits = hits;
    std::sort(sortedHits.begin(), sortedHits.end(), Cmp());
    std::sort(expected.begin(), expected.end(), Cmp());

    CHECK(sortedHits.size() == expected.size(),
          "hit count equals independent-oracle expected count");

    size_t n = std::min(sortedHits.size(), expected.size());
    for (size_t i = 0; i < n; ++i) {
        const auto& h = sortedHits[i];
        const auto& e = expected[i];
        char buf[128];
        std::snprintf(buf, sizeof(buf),
            "hit[%zu] ext=%.5ls fs=%llu sec=%d foot=%d pri=%d",
            i, h.extension.c_str(), (unsigned long long)h.fileStart,
            h.secondaryOk, h.footerOk, h.priority);
        CHECK(h == e, buf);
    }

    // --- negative regions: zero false positives ------------------------------
    for (const auto& h : hits) {
        for (const auto& r : negative) {
            char buf[96];
            std::snprintf(buf, sizeof(buf),
                "false positive: hit at %llu inside negative [%llu,%llu)",
                (unsigned long long)h.fileStart,
                (unsigned long long)r.first, (unsigned long long)r.second);
            CHECK(!(h.fileStart >= r.first && h.fileStart < r.second), buf);
        }
    }

    // --- streaming (512-byte windows) matches single-buffer ------------------
    {
        phoenix::SignatureMatcher stream;
        std::vector<phoenix::MatchPattern> cat2; BuildCatalog(cat2);
        stream.Build(std::move(cat2));
        std::vector<phoenix::SignatureHit> shits;
        const size_t win = 512;
        for (size_t off = 0; off < image.size(); off += win) {
            size_t len = (off + win <= image.size()) ? win : (image.size() - off);
            stream.Feed(image.data() + off, len, off, opt, shits);
        }
        stream.Finish(opt, shits);
        std::sort(shits.begin(), shits.end(), Cmp());
        CHECK(shits.size() == sortedHits.size(),
              "streaming hit count == single-buffer hit count");
        bool same = (shits.size() == sortedHits.size());
        for (size_t i = 0; same && i < shits.size(); ++i)
            if (!(shits[i] == expected[i])) same = false;
        CHECK(same, "streaming hits identical to single-buffer (order-independent)");
    }

    // --- tamper: flipping a magic byte removes exactly that hit -------------
    {
        std::vector<uint8_t> tampered = image;
        tampered[100] ^= 0xFF;   // jpg magic at offset 100
        std::vector<phoenix::SignatureHit> th;
        matcher.Scan(tampered.data(), tampered.size(), 0, opt, th);
        bool jpg100 = false;
        for (auto& h : th)
            if (h.extension == L"jpg" && h.fileStart == 100) jpg100 = true;
        CHECK(!jpg100, "tampered jpg@100 magic no longer matches");
        CHECK(th.size() == hits.size() - 1, "exactly one hit lost after tamper");
    }

    // --- type filter -------------------------------------------------------
    {
        phoenix::MatchOptions o2; o2.alignment = 1;
        o2.allowedExtensions = {L"jpg"};
        std::vector<phoenix::SignatureHit> f;
        matcher.Scan(image.data(), image.size(), 0, o2, f);
        bool onlyJpg = true; size_t jpgCount = 0;
        for (auto& h : f) { if (h.extension != L"jpg") onlyJpg = false; else ++jpgCount; }
        CHECK(onlyJpg, "type filter emits only jpg");
        CHECK(jpgCount == 1 && f[0].fileStart == 100, "type filter keeps jpg@100");
    }

    // --- alignment filter --------------------------------------------------
    {
        phoenix::MatchOptions o3; o3.alignment = 512;
        std::vector<phoenix::SignatureHit> f;
        matcher.Scan(image.data(), image.size(), 0, o3, f);
        // Aligned fileStarts: 2048, 4096, 8192 (all multiples of 512).
        std::vector<uint64_t> got;
        for (auto& h : f) got.push_back(h.fileStart);
        std::sort(got.begin(), got.end());
        std::vector<uint64_t> want = {2048, 4096, 8192};
        bool ok = (got == want);
        CHECK(ok, "alignment=512 keeps exactly png@2048, mp4@4096, cr2@8192");
    }

    if (g_fail == 0) std::printf("ALL SIGNATURE-MATCHER CHECKS PASSED\n");
    else std::printf("%d SIGNATURE-MATCHER CHECK(S) FAILED\n", g_fail);
    return g_fail != 0 ? 1 : 0;
}
